use vstd::prelude::*;

verus! {

pub fn rotate_right(list: &Vec<u32>, n: usize) -> (new_list: Vec<u32>)
    requires
        list.len() > 0,
    ensures
        new_list.len() == list.len(),
        // Rotation-right by (n mod len):
        // new[i] = old[(i + (len - (n mod len))) mod len]
        forall|i: int|
            0 <= i < list.len() ==> {
                let len: int = list.len() as int;
                let shift: int = (n as int) % len;
                let s: int = len - shift;
                new_list[i] == list[((i + s) % len) as usize]
            },
{
    let len = list.len();
    debug_assert!(len > 0, "input list must be non-empty");

    let shift = n % len;
    let s = len - shift; // as specified: s = len - (n mod len)

    let mut new_list = Vec::with_capacity(len);
    new_list.extend_from_slice(&list[s..len]); // suffix [s, len)
    new_list.extend_from_slice(&list[0..s]);   // prefix [0, s)
    new_list
}

} // verus!